import * as THREE from 'three';
import { playGunshot, playReload, playDryFire } from './audio.js';

const HIP_POS = new THREE.Vector3(0.22, -0.22, -0.45);
const ADS_POS = new THREE.Vector3(0, -0.075, -0.3);
const SPRINT_POS = new THREE.Vector3(0.18, -0.28, -0.42);

export class Weapon {
  constructor(camera) {
    this.camera = camera;
    this.fireRate = 60 / 700;     // 700 rpm
    this.magSize = 30;
    this.mag = 30;
    this.reserve = 120;
    this.reloadTime = 2.2;
    this.reloading = 0;
    this.cooldown = 0;
    this.adsAmount = 0;           // 0 = hip, 1 = sighted
    this.recoilKick = 0;          // pitch impulse consumed by the player controller
    this.swayX = 0; this.swayY = 0;
    this.onShot = null;           // set by main

    this.group = new THREE.Group();
    this.buildModel();
    this.group.position.copy(HIP_POS);
    camera.add(this.group);
  }

  buildModel() {
    const black = new THREE.MeshStandardMaterial({ color: 0x1a1b1d, roughness: 0.45, metalness: 0.6 });
    const poly  = new THREE.MeshStandardMaterial({ color: 0x26282b, roughness: 0.7, metalness: 0.2 });
    const tan   = new THREE.MeshStandardMaterial({ color: 0x6b5d42, roughness: 0.8 });
    const g = this.group;
    const add = (geo, mat, x, y, z) => {
      const m = new THREE.Mesh(geo, mat);
      m.position.set(x, y, z);
      g.add(m);
      return m;
    };
    // receiver
    add(new THREE.BoxGeometry(0.05, 0.075, 0.26), black, 0, 0, 0);
    // handguard + barrel + muzzle device
    add(new THREE.BoxGeometry(0.045, 0.055, 0.24), tan, 0, 0.004, -0.25);
    add(new THREE.CylinderGeometry(0.009, 0.009, 0.16, 10), black, 0, 0.01, -0.45).rotation.x = Math.PI / 2;
    add(new THREE.CylinderGeometry(0.014, 0.014, 0.05, 10), black, 0, 0.01, -0.54).rotation.x = Math.PI / 2;
    // stock + grip + magazine
    add(new THREE.BoxGeometry(0.04, 0.06, 0.16), poly, 0, -0.005, 0.2);
    add(new THREE.BoxGeometry(0.035, 0.09, 0.045), poly, 0, -0.075, 0.05);
    const mag = add(new THREE.BoxGeometry(0.035, 0.13, 0.06), poly, 0, -0.1, -0.04);
    mag.rotation.x = 0.15;
    this.magMesh = mag;
    // iron sights: rear aperture ring + front post, define the ADS sight line at y=+0.075
    const ring = add(new THREE.TorusGeometry(0.011, 0.003, 6, 14), black, 0, 0.075, 0.1);
    ring.rotation.y = 0; // faces camera
    add(new THREE.BoxGeometry(0.003, 0.018, 0.003), black, 0, 0.068, -0.36);
    add(new THREE.BoxGeometry(0.02, 0.006, 0.01), black, 0, 0.058, -0.36);

    // muzzle reference + flash
    this.muzzle = new THREE.Object3D();
    this.muzzle.position.set(0, 0.01, -0.57);
    g.add(this.muzzle);
    this.flashLight = new THREE.PointLight(0xffc080, 0, 5, 2);
    this.flashLight.position.copy(this.muzzle.position);
    g.add(this.flashLight);
    const flashMat = new THREE.MeshBasicMaterial({
      color: 0xffd9a0, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false,
    });
    this.flashMesh = new THREE.Mesh(new THREE.PlaneGeometry(0.14, 0.14), flashMat);
    this.flashMesh.position.copy(this.muzzle.position);
    g.add(this.flashMesh);

    // keep the viewmodel out of the sun's shadow pass
    g.traverse(o => { o.castShadow = false; o.receiveShadow = false; });
  }

  get canADS() { return this.reloading <= 0; }

  startReload() {
    if (this.reloading > 0 || this.mag === this.magSize || this.reserve <= 0) return;
    this.reloading = this.reloadTime;
    playReload();
  }

  // input: { firing, wantADS, sprinting, moveSpeed, mouseDX, mouseDY }
  update(dt, input) {
    this.cooldown -= dt;

    if (this.reloading > 0) {
      this.reloading -= dt;
      if (this.reloading <= 0) {
        const need = this.magSize - this.mag;
        const take = Math.min(need, this.reserve);
        this.mag += take;
        this.reserve -= take;
      }
    }

    // ADS blend
    const adsTarget = (input.wantADS && this.canADS && !input.sprinting) ? 1 : 0;
    this.adsAmount += (adsTarget - this.adsAmount) * Math.min(1, dt * 12);

    // firing
    if (input.firing && this.cooldown <= 0 && this.reloading <= 0) {
      if (this.mag > 0) {
        this.mag--;
        this.cooldown = this.fireRate;
        this.recoilKick += THREE.MathUtils.degToRad(0.55) * (1 - this.adsAmount * 0.35);
        this.flashLight.intensity = 30;
        this.flashMesh.material.opacity = 1;
        this.flashMesh.rotation.z = Math.random() * Math.PI;
        const s = 0.8 + Math.random() * 0.7;
        this.flashMesh.scale.set(s, s, s);
        this.kickback = 0.035;
        playGunshot();
        if (this.onShot) this.onShot(this.currentSpread(input));
      } else {
        this.cooldown = 0.3;
        playDryFire();
      }
    }

    // muzzle flash decay
    this.flashLight.intensity *= Math.pow(0.000001, dt);
    this.flashMesh.material.opacity *= Math.pow(0.000001, dt);

    // weapon sway from mouse movement (drag opposite to look direction)
    this.swayX += (-input.mouseDX * 0.00012 - this.swayX) * Math.min(1, dt * 8);
    this.swayY += (input.mouseDY * 0.00012 - this.swayY) * Math.min(1, dt * 8);
    const swayScale = 1 - this.adsAmount * 0.8;

    // position: blend hip/ads/sprint
    const base = new THREE.Vector3();
    if (input.sprinting) base.copy(SPRINT_POS);
    else base.lerpVectors(HIP_POS, ADS_POS, this.adsAmount);

    // idle breathing bob
    const t = performance.now() / 1000;
    base.y += Math.sin(t * 1.7) * 0.0015 * swayScale;
    base.x += this.swayX * swayScale * 30 * 0.01;
    base.y += this.swayY * swayScale * 30 * 0.01;

    // recoil kickback along barrel
    this.kickback = (this.kickback || 0) * Math.pow(0.001, dt);
    base.z += this.kickback;

    // reload dip
    if (this.reloading > 0) {
      const p = 1 - this.reloading / this.reloadTime;
      base.y -= Math.sin(p * Math.PI) * 0.12;
      this.group.rotation.x = -Math.sin(p * Math.PI) * 0.5;
      this.magMesh.visible = p < 0.25 || p > 0.62;
    } else {
      this.group.rotation.x *= Math.pow(0.001, dt);
      this.magMesh.visible = true;
    }

    // sprint canting
    const targetRotZ = input.sprinting ? -0.35 : 0;
    const targetRotY = input.sprinting ? 0.3 : 0;
    this.group.rotation.z += (targetRotZ - this.group.rotation.z) * Math.min(1, dt * 8);
    this.group.rotation.y += (targetRotY - this.group.rotation.y) * Math.min(1, dt * 8);

    this.group.position.lerp(base, Math.min(1, dt * 14));
  }

  currentSpread(input) {
    const hip = 0.022;
    const ads = 0.0012;
    let spread = THREE.MathUtils.lerp(hip, ads, this.adsAmount);
    spread += input.moveSpeed * 0.0022;
    return spread;
  }

  muzzleWorldPos(target) {
    return this.muzzle.getWorldPosition(target);
  }
}
